18:    /// Determines which of all the file filter options to use.
19:    pub fn deduce(matches: &MatchedFlags<'_>) -> Result<Self, OptionsError> {
20:        use FileFilterFlags as FFF;
21:        let mut filter_flags: Vec<FileFilterFlags> = vec![];
22:
23:        for (has, flag) in &[
24:            (matches.has(&flags::REVERSE)?, FFF::Reverse),
25:            (matches.has(&flags::ONLY_DIRS)?, FFF::OnlyDirs),
26:            (matches.has(&flags::ONLY_FILES)?, FFF::OnlyFiles),
27:            (matches.has(&flags::NO_SYMLINKS)?, FFF::NoSymlinks),
28:            (matches.has(&flags::SHOW_SYMLINKS)?, FFF::ShowSymlinks),
29:            (matches.has(&flags::DIRS_LAST)?, FFF::ListDirsLast),
30:            (matches.has(&flags::DIRS_FIRST)?, FFF::ListDirsFirst),
31:        ] {
32:            if *has {
33:                filter_flags.push(flag.clone());
34:            }
35:        }
36:
37:        #[rustfmt::skip]
38:        return Ok(Self {
39:            no_symlinks:      filter_flags.contains(&FFF::NoSymlinks),
40:            show_symlinks:    filter_flags.contains(&FFF::ShowSymlinks),
41:            flags:            filter_flags,
42:            sort_field:       SortField::deduce(matches)?,
43:            dot_filter:       DotFilter::deduce(matches)?,
44:            ignore_patterns:  IgnorePatterns::deduce(matches)?,
45:            git_ignore:       GitIgnore::deduce(matches)?,
46:        });
47:    }
